<script setup lang="ts">
import { onBeforeMount,onMounted,ref } from 'vue';import { useRunStore } from './stores/run';import StartScreen from './components/StartScreen.vue';import TimerBar from './components/TimerBar.vue';import QuestionCard from './components/QuestionCard.vue';import ResultsView from './components/ResultsView.vue';
const store=useRunStore();const cards=ref<Record<number,any>>({});onBeforeMount(store.load);onMounted(()=>document.addEventListener('visibilitychange',()=>{if(!document.hidden)store.resync()}));async function reveal(id:number){const options=await store.reveal(id);cards.value[id]?.setOptions(options)}async function answer(id:number,stage:'free_text'|'multiple_choice',value:string){const a=await store.answer(id,stage,value);if(stage==='free_text'&&!a.outcome){const options=await store.reveal(id);cards.value[id]?.setOptions(options)}}
</script>
<template><div v-if="store.loading" class="loading">Preparing today’s board…</div><div v-else-if="store.error" class="loading"><h1>Not today.</h1><p>{{store.error}}</p></div><ResultsView v-else-if="store.complete"/><StartScreen v-else-if="!store.run" :puzzle="store.puzzle!" @start="store.start"/><main v-else class="game"><header class="game-head"><div><p class="eyebrow">Trivial · {{store.puzzle!.date}}</p><h1>Today’s board</h1></div><TimerBar :remaining="store.remainingMs" :total="store.puzzle!.time_limit_seconds"/></header><section v-for="pos in [0,1,2]" :key="pos" class="topic-row"><h2>{{store.puzzle!.questions.find(q=>q.topic_position===pos)!.topic_name}}</h2><div><QuestionCard v-for="q in store.puzzle!.questions.filter(q=>q.topic_position===pos)" :key="q.question_id" :ref="el=>cards[q.question_id]=el" :question="q" :answer="store.answerMap.get(q.question_id)" :disabled="store.remainingMs===0" @reveal="reveal" @answer="answer"/></div></section><button class="give-up" @click="store.finish">Finish early</button></main></template>
